public class Mystery { public static int skeleton(int x,int y){return x/y%2;} public static int witch(int x,int y){x=10*x+y;System.out.println("witch: x = "+x+", y = "+y);return x;} public static void main(String[] a){int x=13,y=0;for(int i=1;i<x;i*=2)y=witch(y,skeleton(x,i));System.out.println("ghost: x = "+x+", y = "+y);}}
